exercises.solution:
@Service
public class RankingService {
    private static final String KLUCZ = "ranking:global";
    private final StringRedisTemplate redis;
    public RankingService(StringRedisTemplate redis) { this.redis = redis; }

    public record Pozycja(int miejsce, String gracz, double punkty) {}

    public void dodajPunkty(String gracz, double pkt) {
        redis.opsForZSet().incrementScore(KLUCZ, gracz, pkt);
    }

    public List<Pozycja> top10() {
        Set<ZSetOperations.TypedTuple<String>> wynik = redis.opsForZSet().reverseRangeWithScores(KLUCZ, 0, 9);
        List<Pozycja> lista = new ArrayList<>();
        int miejsce = 1;
        for (var t : wynik) lista.add(new Pozycja(miejsce++, t.getValue(), t.getScore()));
        return lista;
    }

    public Optional<Integer> miejsce(String gracz) {
        Long rank = redis.opsForZSet().reverseRank(KLUCZ, gracz);
        return rank == null ? Optional.empty() : Optional.of(rank.intValue() + 1);
    }
}
reverseRank odpowiada ZREVRANK (liczony od 0), stąd +1. Punkty nadal zapisuje się w bazie - Sorted Set można w razie utraty odbudować z bazy.

